import math
from itertools import combinations

def min_angle_pair(vectors):
    def dot_product(v1, v2):
        return v1[0] * v2[0] + v1[1] * v2[1]

    def magnitude(v):
        return math.sqrt(dot_product(v, v))

    def angle_between(v1, v2):
        cos_theta = dot_product(v1, v2) / (magnitude(v1) * magnitude(v2))
        return math.acos(max(-1.0, min(1.0, cos_theta)))

    min_angle = float('inf')
    min_pair = None

    for v1, v2 in combinations(vectors, 2):
        current_angle = angle_between(v1, v2)
        if current_angle < min_angle:
            min_angle = current_angle
            min_pair = (vectors.index(v1) + 1, vectors.index(v2) + 1)

    return min_pair

# Example usage:
n = int(input())
vectors = [tuple(map(int, input().split())) for _ in range(n)]
result = min_angle_pair(vectors)
